parameters.jsCode:
// Der Feed liefert immer die letzten ~10 Artikel. Ohne Gedaechtnis wuerde jeder
// Lauf denselben Newsletter erzeugen. Der Zeitstempel des letzten erfolgreichen
// Laufs liegt deshalb in den statischen Workflow-Daten - die ueberleben einen
// Neustart, sind aber nur in AKTIVEN Workflows persistent (im manuellen Testlauf
// wird nichts gespeichert).
const merker = $getWorkflowStaticData('global');

// Erster Lauf: 7 Tage zurueck, damit nicht das ganze Blog-Archiv im Newsletter landet.
const standard = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const stichtag = merker.letzter_lauf ? new Date(merker.letzter_lauf) : standard;

const neue = [];
for (const eintrag of $input.all()) {
  const a = eintrag.json;
  const datum = new Date(a.isoDate ?? a.pubDate ?? a.date ?? 0);
  if (isNaN(datum.getTime()) || datum <= stichtag) continue;

  // HTML aus der Feed-Vorschau entfernen: Markup kostet nur Tokens und
  // verleitet das Modell dazu, Tags in den Newsletter zu uebernehmen.
  const roh = String(a.contentSnippet ?? a.content ?? a.summary ?? '');
  const text = roh.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

  neue.push({
    titel: a.title ?? '(ohne Titel)',
    link: a.link ?? '',
    datum_de: datum.toLocaleDateString('de-DE'),
    datum_iso: datum.toISOString(),
    anriss: text.slice(0, 1200),
    kategorien: Array.isArray(a.categories) ? a.categories : []
  });
}

// Neueste zuerst, maximal 6 Artikel - laengere Newsletter werden erfahrungsgemaess
// nicht mehr zu Ende gelesen.
neue.sort((x, y) => new Date(y.datum_iso) - new Date(x.datum_iso));
const auswahl = neue.slice(0, 6);

return [{
  json: {
    anzahl_neu: auswahl.length,
    uebersprungen: Math.max(0, neue.length - auswahl.length),
    stichtag_iso: stichtag.toISOString(),
    stichtag_de: stichtag.toLocaleDateString('de-DE'),
    lauf_iso: new Date().toISOString(),
    artikel: auswahl,
    artikel_text: auswahl.map((a, i) => `${i + 1}. ${a.titel} (${a.datum_de})\nLink: ${a.link}\n${a.anriss}`).join('\n\n')
  }
}];

// Zwei Aufgaben: pruefen, ob der Entwurf ueberhaupt versandfaehig ist, und die
// Kennzeichnung nach Art. 50 EU AI Act fest an den Text haengen. Der Hinweis
// wird hier und nicht im Prompt gesetzt - so kann das Modell ihn nicht
// "wegformulieren" und der Wortlaut bleibt in jedem Lauf identisch.
const KENNZEICHNUNG = 'Dieser Newsletter wurde mit Unterstuetzung von KI erstellt und vor dem Versand redaktionell geprueft.';
const MAX_BETREFF = 60;

const quelle = $('Neue Artikel seit letztem Lauf').first().json;
const e = $input.first().json.message?.content ?? $input.first().json;

const maengel = [];
const betreffA = String(e.betreff_a ?? '').trim();
const betreffB = String(e.betreff_b ?? '').trim();
const artikel = Array.isArray(e.artikel) ? e.artikel : [];

if (!betreffA || !betreffB) maengel.push('Es fehlt eine der beiden Betreffzeilen fuer den A/B-Test');
if (betreffA && betreffA === betreffB) maengel.push('Beide Betreffzeilen sind identisch - kein sinnvoller A/B-Test');
if (betreffA.length > MAX_BETREFF || betreffB.length > MAX_BETREFF) maengel.push('Betreffzeile laenger als ' + MAX_BETREFF + ' Zeichen - wird in Mail-Clients abgeschnitten');
if (artikel.length !== quelle.anzahl_neu) maengel.push(`Modell hat ${artikel.length} statt ${quelle.anzahl_neu} Artikel zusammengefasst`);

// Erfundene Links sind der haeufigste Fehler: jeder Link muss aus dem Feed stammen.
const echteLinks = new Set(quelle.artikel.map(a => a.link));
const fremdeLinks = artikel.map(a => a.link).filter(l => l && !echteLinks.has(l));
if (fremdeLinks.length) maengel.push('Nicht aus dem Feed stammende Links: ' + fremdeLinks.join(', '));

const html = [
  `<p>${e.einleitung ?? ''}</p>`,
  ...artikel.map(a => `<h2>${a.titel}</h2><p>${a.zusammenfassung}</p><p><a href="${a.link}">${a.cta || 'Zum Artikel'}</a></p>`),
  `<p>${e.abschluss ?? ''}</p>`,
  `<hr><p style="font-size:12px;color:#666">${KENNZEICHNUNG}</p>`
].join('\n');

return [{
  json: {
    betreff_a: betreffA,
    betreff_b: betreffB,
    preheader: e.preheader ?? '',
    html,
    text_vorschau: [e.einleitung, ...artikel.map(a => `${a.titel}: ${a.zusammenfassung} ${a.link}`), e.abschluss, KENNZEICHNUNG].filter(Boolean).join('\n\n'),
    artikel_anzahl: artikel.length,
    kennzeichnung: KENNZEICHNUNG,
    maengel,
    versandfaehig: maengel.length === 0,
    lauf_iso: quelle.lauf_iso
  }
}];

// Der Merker wird erst JETZT gesetzt - nach dem erfolgreichen Anlegen des
// Entwurfs. Waere er schon im Filter gesetzt worden, waeren die Artikel bei
// einem Fehler im KI- oder API-Schritt fuer immer verloren: der naechste Lauf
// haette sie als "schon verarbeitet" uebersprungen.
const merker = $getWorkflowStaticData('global');
const entwurf = $('Entwurf pruefen und kennzeichnen').first().json;
merker.letzter_lauf = entwurf.lauf_iso;
merker.letzte_artikelzahl = entwurf.artikel_anzahl;

return [{ json: { ...entwurf, merker_gesetzt_auf: merker.letzter_lauf } }];

parameters.text:
=Im Newsletter-Tool liegt ein neuer Entwurf zur Freigabe.

Betreff Variante A: {{ $json.betreff_a }}
Betreff Variante B: {{ $json.betreff_b }}
Preheader: {{ $json.preheader }}
Artikel im Newsletter: {{ $json.artikel_anzahl }}

A/B-Test ist vorbereitet: 20 Prozent Testversand, Gewinner nach Oeffnungsrate, Entscheidung nach 4 Stunden.

Textvorschau:
{{ $json.text_vorschau }}

Hinweis zur Kennzeichnung: {{ $json.kennzeichnung }}
Dieser Satz steht im Fuss des Entwurfs und sollte dort bleiben (Art. 50 EU AI Act).

Der Newsletter wurde NICHT versendet. Bitte im Tool pruefen und von Hand freigeben.
